"""Audit actual revision artifacts; never equate structural checks to visual acceptance."""
from pathlib import Path
from PIL import Image,ImageChops
import io,json,zipfile,hashlib,xml.etree.ElementTree as ET,re
P=Path(__file__).resolve().parent;ROOT=P.parents[3];OUT=ROOT/'output/art/rc-011/r002'
checks=[]
def check(ok,name,evidence):checks.append({'check':name,'result':'pass' if ok else 'FAIL','evidence':str(evidence)})
for path,size in [('exports/shadeling.png',(512,512)),('exports/spark_tile.png',(256,256)),('exports/button_primary_normal.png',(512,128)),('exports/button_secondary_normal.png',(512,128))]:
    im=Image.open(P/path);check(im.size==size and im.mode=='RGBA','Export size/RGBA '+path,im.size);check(bool(im.info.get('icc_profile')),'sRGB '+path,'embedded ICC')
for path in [P/'shadeling.ora',*list((P/'ui').glob('*.ora'))]:
    with zipfile.ZipFile(path) as z:
        tree=ET.fromstring(z.read('stack.xml'));layers=tree.findall('.//layer');size=(int(tree.get('w')),int(tree.get('h')));merged=Image.new('RGBA',size);digests=[]
        check(z.read('mimetype')==b'image/openraster','ORA format',path.name)
        for layer in reversed(layers):
            im=Image.open(io.BytesIO(z.read(layer.get('src')))).convert('RGBA');digests.append(hashlib.sha256(im.tobytes()).hexdigest())
            check(im.size==size and im.getchannel('A').getbbox() is not None,'nonempty full-canvas layer',path.name+'/'+layer.get('name'));merged.alpha_composite(im)
        check(len(set(digests))==len(layers),'distinct genuine layers',path.name)
        stored=Image.open(io.BytesIO(z.read('mergedimage.png'))).convert('RGBA')
        check(ImageChops.difference(stored,merged).getbbox() is None,'exact ORA recomposition',path.name)
meta=json.loads((P/'metadata.json').read_text());neutral=Image.new('RGBA',(512,512))
for name in meta['draw_order']:
    im=Image.open(P/f'exports/shadeling_parts/{name}.png').convert('RGBA');check(im.size==(512,512),'shared part canvas',name);neutral.alpha_composite(im)
check(ImageChops.difference(neutral,Image.open(P/'exports/shadeling.png')).getbbox() is None,'part export recomposition','seven independent parts')
check(meta['source_foot']==[512,896] and meta['export_foot']==[256,448],'foot anchor','metadata and assembly source')
frames=list((OUT/'pilot-motion-frames').glob('frame_*.png'));timing=json.loads((OUT/'pilot-motion-timing.json').read_text())
check(len(frames)==48 and len(timing['frames'])==96 and timing['fps']==8,'motion sequence with reduced counterpart','48 frames / 96 records / 8fps')
for rec in timing['frames']:
    b=rec['alpha_bounds_all'];check(b is None or (b[0]>=32 and b[1]>=32 and b[2]<=480 and b[3]<=480),'motion envelope',str(rec['frame'])+'/'+str(rec['reduced']))
sizes={'pilot-720x1600.png':(720,1600),'pilot-450x1000.png':(450,1000),'pilot-360x640.png':(360,640),'pilot-360x640-controls.png':(360,640),'pilot-360x640-inspector.png':(360,640),'pilot-states.png':(1440,2280),'pilot-type.png':(1100,1230)}
for name,size in sizes.items():check(Image.open(OUT/name).size==size,'preview dimensions '+name,size)
ns='{http://www.w3.org/2000/svg}';xl='{http://www.w3.org/1999/xlink}'
for path in list(P.glob('pilot*.svg'))+list((P/'ui').glob('*.svg')):
    tree=ET.parse(path).getroot()
    if path.parent==P:check(len(tree.findall('.//'+ns+'text'))>0,'live editable text',path.name)
    for el in tree.iter():
        ref=el.get(xl+'href') or el.get('href')
        if ref and not ref.startswith('data:'):check((path.parent/ref).resolve().exists(),'SVG linked file',path.name+': '+ref)
g=ET.parse(P/'exports/spark.svg').getroot();check(g.get('viewBox')=='0 0 128 128','Spark viewBox','128x128')
check(not any(el.tag.split('}')[-1] in ['text','image','filter','use'] for el in g.iter()),'Spark vector only','no live data or dependencies baked in')
contract=json.loads((P/'type-geometry/spark-geometry-contract.json').read_text())
check(contract['ports']=={'N':[64,0],'E':[128,64],'S':[64,128],'W':[0,64]},'exact ports',contract['ports'])
fmeta=json.loads((P/'type-geometry/font-provenance.json').read_text());f=P/'type-geometry/fonts/NotoSerif-Variable.ttf'
check(hashlib.sha256(f.read_bytes()).hexdigest()==fmeta['font_sha256'],'actual font hash','Noto Serif2.015')
check((P/'type-geometry/fonts/OFL.NotoSerif.txt').exists(),'actual font licence','official OFL acquired with font')
check(hashlib.sha256((P/'raw/shadeling.png').read_bytes()).hexdigest()==meta['generation']['raw_sha256'],'retained raw generation','exact generated bytes')
check(hashlib.sha256((ROOT/'output/imagegen/approved/combat.png').read_bytes()).hexdigest()==meta['generation']['reference_sha256'],'approved Combat preserved','original referenced bytes')
check((ROOT/'source-assets/.gdignore').exists() and (ROOT/'output/.gdignore').exists(),'source exclusion','main project not integrated')
failed=[c for c in checks if c['result']=='FAIL']
report={'revision':'r002','structural_result':'pass' if not failed else 'FAIL','check_count':len(checks),'failures':failed,'visual_result':'revise; improved pilot assets; full reference appearance not yet reproduced','checks':checks}
(OUT/'revision-validation.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:report[k] for k in ['revision','structural_result','check_count','failures','visual_result']},indent=2))
raise SystemExit(bool(failed))
